def regex_search(pattern: str, text: str) -> bool:
    if pattern == "":
        return True

    states_eps: list[list[tuple[int, int]]] = []
    states_trans: list[list[tuple[int, int, object]]] = []
    class_infos: list[tuple[bool, list[tuple[int, int]], dict[int, bool]]] = []

    def new_state() -> int:
        states_eps.append([])
        states_trans.append([])
        return len(states_eps) - 1

    def add_epsilon(u: int, v: int, cond: int = 0) -> None:
        states_eps[u].append((v, cond))

    def add_char_transition(u: int, v: int, ch: str) -> None:
        states_trans[u].append((1, v, ch))

    def add_any_transition(u: int, v: int) -> None:
        states_trans[u].append((0, v, None))

    def add_class_transition(u: int, v: int, neg: bool, ranges: list[tuple[int, int]]) -> None:
        ranges = sorted(ranges)
        merged: list[tuple[int, int]] = []
        for a, b in ranges:
            if not merged or a > merged[-1][1] + 1:
                merged.append((a, b))
            elif b > merged[-1][1]:
                merged[-1] = (merged[-1][0], b)

        cid = len(class_infos)
        class_infos.append((neg, merged, {}))
        states_trans[u].append((2, v, cid))

    pat = pattern
    p_len = len(pat)
    idx = 0

    def parse_alt(stop_extra: set[str]) -> tuple[int, int]:
        nonlocal idx

        alt_start = new_state()
        alt_end = new_state()

        while True:
            seq_start, seq_end = parse_seq(stop_extra)
            add_epsilon(alt_start, seq_start, 0)
            add_epsilon(seq_end, alt_end, 0)

            if idx < p_len and pat[idx] == "|":
                idx += 1
                continue

            return alt_start, alt_end

    def parse_seq(stop_extra: set[str]) -> tuple[int, int]:
        nonlocal idx

        seq_start = new_state()
        cur = seq_start

        while idx < p_len and pat[idx] != "|" and pat[idx] not in stop_extra:
            if pat[idx] in "*+?":
                raise ValueError("quantifier with no operand")

            a_start, a_end, quantifiable = parse_atom()

            if idx < p_len and pat[idx] in "*+?":
                if not quantifiable:
                    raise ValueError("quantifier after anchor")

                op = pat[idx]
                idx += 1

                if idx < p_len and pat[idx] in "*+?":
                    raise ValueError("overlapped quantifiers")

                if op == "*":
                    q_start = new_state()
                    q_end = new_state()
                    add_epsilon(q_start, a_start, 0)
                    add_epsilon(q_start, q_end, 0)
                    add_epsilon(a_end, q_start, 0)
                    a_start, a_end = q_start, q_end
                elif op == "+":
                    add_epsilon(a_end, a_start, 0)
                else:
                    q_end = new_state()
                    add_epsilon(a_start, q_end, 0)
                    add_epsilon(a_end, q_end, 0)
                    a_start, a_end = a_start, q_end

            add_epsilon(cur, a_start, 0)
            cur = a_end

        return seq_start, cur

    def parse_atom() -> tuple[int, int, bool]:
        nonlocal idx

        if idx >= p_len:
            raise ValueError("missing operand")

        c = pat[idx]

        if c == "(":
            idx += 1
            g_start, g_end = parse_alt({")"})
            if idx >= p_len or pat[idx] != ")":
                raise ValueError("missing matching parenthesis")
            idx += 1
            return g_start, g_end, True

        if c == "[":
            return parse_char_class()

        if c == "\\":
            if idx + 1 >= p_len:
                raise ValueError("trailing backslash")
            ch = pat[idx + 1]
            idx += 2
            s = new_state()
            e = new_state()
            add_char_transition(s, e, ch)
            return s, e, True

        if c == ".":
            idx += 1
            s = new_state()
            e = new_state()
            add_any_transition(s, e)
            return s, e, True

        if c == "^":
            idx += 1
            s = new_state()
            e = new_state()
            add_epsilon(s, e, 1)
            return s, e, False

        if c == "$":
            idx += 1
            s = new_state()
            e = new_state()
            add_epsilon(s, e, 2)
            return s, e, False

        if c == ")":
            raise ValueError("unmatched right parenthesis")

        if c in "*+?":
            raise ValueError("quantifier with no operand")

        idx += 1
        s = new_state()
        e = new_state()
        add_char_transition(s, e, c)
        return s, e, True

    def parse_char_class() -> tuple[int, int, bool]:
        nonlocal idx

        if idx >= p_len or pat[idx] != "[":
            raise ValueError("invalid character class")

        idx += 1
        neg = False

        if idx < p_len and pat[idx] == "^":
            neg = True
            idx += 1

        ranges: list[tuple[int, int]] = []
        item_count = 0

        while True:
            if idx >= p_len:
                raise ValueError("unclosed character class")

            if pat[idx] == "]":
                if item_count == 0:
                    raise ValueError("empty character class")
                idx += 1
                break

            if pat[idx] == "\\":
                if idx + 1 >= p_len:
                    raise ValueError("trailing backslash inside character class")
                x = pat[idx + 1]
                idx += 2
            else:
                x = pat[idx]
                idx += 1

            item_count += 1

            if idx < p_len and pat[idx] == "-":
                if idx + 1 < p_len and pat[idx + 1] != "]":
                    if pat[idx + 1] == "\\":
                        if idx + 2 >= p_len:
                            raise ValueError("trailing backslash inside character class")
                        y = pat[idx + 2]
                        idx += 3
                    else:
                        y = pat[idx + 1]
                        idx += 2

                    ox = ord(x)
                    oy = ord(y)
                    if ox > oy:
                        raise ValueError("invalid character class range")
                    ranges.append((ox, oy))
                    continue

                ranges.append((ord(x), ord(x)))
                continue

            ranges.append((ord(x), ord(x)))

        s = new_state()
        e = new_state()
        add_class_transition(s, e, neg, ranges)
        return s, e, True

    top_start, top_end = parse_alt(set())
    if idx != p_len:
        raise ValueError("invalid pattern")

    def epsilon_closure(initial: set[int], pos: int) -> set[int]:
        reached = set(initial)
        stack = list(reached)

        while stack:
            state = stack.pop()
            for nxt, cond in states_eps[state]:
                if cond == 0:
                    if nxt not in reached:
                        reached.add(nxt)
                        stack.append(nxt)
                elif cond == 1:
                    if pos == 0 and nxt not in reached:
                        reached.add(nxt)
                        stack.append(nxt)
                elif cond == 2:
                    if pos == text_len and nxt not in reached:
                        reached.add(nxt)
                        stack.append(nxt)

        return reached

    def class_match(cid: int, ch: str) -> bool:
        neg, ranges, cache = class_infos[cid]

        if ch in cache:
            return cache[ch]

        code = ord(ch)
        inside = False
        for a, b in ranges:
            if a <= code <= b:
                inside = True
                break

        result = not inside if neg else inside
        cache[ch] = result
        return result

    text_len = len(text)
    current: set[int] = set()

    for pos in range(text_len + 1):
        current = epsilon_closure(current | {top_start}, pos)

        if top_end in current:
            return True

        if pos == text_len:
            break

        ch = text[pos]
        nxt_states: set[int] = set()

        for st in current:
            for kind, target, payload in states_trans[st]:
                if kind == 0:
                    nxt_states.add(target)
                elif kind == 1:
                    if payload == ch:
                        nxt_states.add(target)
                else:
                    if class_match(payload, ch):
                        nxt_states.add(target)

        current = nxt_states

    return False
